arguments.command:
python3 -c "
from sentence_transformers import SentenceTransformer
# Check if any model is already cached
import os
cache = os.path.expanduser('~/.cache/huggingface')
if os.path.exists(cache):
    for root, dirs, files in os.walk(cache):
        for f in files:
            if f.endswith('.json') or f.endswith('.bin') or f.endswith('.safetensors'):
                print(os.path.join(root, f))
else:
    print('No cache dir at', cache)

# Also check torch hub
cache2 = os.path.expanduser('~/.cache/torch')
if os.path.exists(cache2):
    for root, dirs, files in os.walk(cache2):
        for f in files:
            print(os.path.join(root, f))
else:
    print('No torch cache at', cache2)
" 2>&1

